/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('payments')` (or `ctx.tryUse` for an optional dependency). */
export interface PaymentsPublicApi {
  /** Accepted brands, saved methods, wallet availability and a setup session for a new card Used by: checkout. */
  listOptions(owner: { customerId?: string, guestSessionId?: string }, amount: common.Money): Promise<PaymentOptions>;
  /** Create an intent for a checkout attempt and authorize it. Returns accepted, failed (with decline), pending_check (uncertain) or requires_action. Only one non-failed intent per checkout session at a time; the same key returns the first result. Used by: checkout. */
  authorize(input: AuthorizeInput, idempotencyKey: string): Promise<AuthorizeResult>;
  /** Attach the created order and its seller-group allocations. Also done on orders.order.placed. Used by: checkout. */
  linkOrder(intentId: string, orderId: string, allocations: Allocation[]): Promise<void>;
  /** Finish an authorization after a bank challenge or wallet confirmation (checkout calls it from POST /sessions/{id}/complete-action) Used by: checkout. */
  completeAction(intentId: string, resultToken: string, idempotencyKey: string): Promise<AuthorizeResult>;
  /** Current customer-facing state; refresh asks the provider first Used by: checkout. */
  getIntentStatus(intentId: string, refresh?: boolean): Promise<PaymentStatusView>;
  /** Release an authorization (abandoned checkout, order cancelled before capture) Used by: checkout. */
  voidIntent(intentId: string, reason: string): Promise<void>;
  /** Per item: paid, refunded, in flight (requested, processing and failed refunds) and remaining. The cap for every refund. Used by: returns, orders, support, finance. */
  remainingRefundable(orderId: string, orderItemIds?: string[]): Promise<RefundableSummary>;
  /** Hand over an approved refund for execution. Fails with REFUND_EXCEEDS_REFUNDABLE or DUPLICATE_REFUND. Returns the existing refund for the same key or origin. Used by: returns, finance, support. */
  startRefund(input: StartRefundInput, idempotencyKey: string): Promise<Refund>;
  /** Execution status for mirrors in returns, support and orders Used by: returns, support, orders. */
  getRefund(refundId: string): Promise<Refund | null>;
  /** e.g. 'Visa •••• 4417', from the snapshot (stays after the saved card is removed) Used by: orders, returns. */
  methodLabel(intentId: string): Promise<string>;
  /** The order's accepted payment intent. Callers show the customer view (customerState, method label, amounts) to customers and the full detail to staff. Used by: graphql. */
  getPaymentForOrder(orderId: string): Promise<PaymentDetail | null>;
  /** Refund executions of an order, newest first, with items and status (Requested, Processing, Sent, Failed, Cancelled) Used by: graphql. */
  listRefundsForOrder(orderId: string): Promise<Refund[]>;
  /** Chargebacks and payment disputes on an order (order 360, dispute case) Used by: graphql. */
  listDisputesForOrder(orderId: string): Promise<Dispute[]>;
  /** The customer's saved cards and wallets, default first Used by: graphql. */
  listSavedMethods(customerId: string): Promise<SavedPaymentMethod[]>;
  /** Payments of the customer that failed after their order was placed (an uncertain payment finally declined, so orders cancelled the order), failed since `since`, newest first, at most 5. For the account overview's payment_failed alert Used by: customers. */
  listFailedPaymentsForCustomer(customerId: string, since: string): Promise<PaymentStatusView[]>;
  /** The customer's payment data for the personal data export: saved payment methods masked (brand, last 4, expiry, label, billing city and postal code; never a provider token), payments (reference, order, amount, method label, status, dates; declines with their plain reason) and refunds (reference, order, amount, destination label, status, dates). No provider references, card fingerprints or staff notes. Export hook called by customers.build-data-exports Used by: customers. */
  exportCustomerData(input: { customerId: string, accountId: string }): Promise<common.CustomerDataSection[]>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`payments.<table>`, ctx.mongo.table(name)). */
export interface PaymentsDb {
  /** One per checkout payment attempt */
  intents: {
    id: string;
    ref: string;
    checkout_session_id: string;
    attempt_no: number;
    order_id: string | null;
    customer_id: string | null;
    guest_email: string | null;
    amount: number;
    currency: string;
    tenders: Json;
    /** MethodSnapshot */
    method: Json;
    provider: string;
    provider_ref: string | null;
    status: 'created' | 'authorizing' | 'requires_action' | 'pending_check' | 'authorized' | 'partially_captured' | 'captured' | 'failed' | 'voided' | 'expired';
    decline: Json | null;
    /** NextAction: the bank challenge waiting for the customer while the intent is requires_action; cleared when it ends */
    next_action: Json | null;
    authorized_amount: number;
    captured_amount: number;
    refunded_amount: number;
    authorized_at: Date | null;
    captured_at: Date | null;
    authorization_expires_at: Date | null;
    last_checked_at: Date | null;
    next_check_at: Date | null;
    check_attempts: number;
    orphan: boolean;
    idempotency_key: string;
    created_at: Date;
    updated_at: Date;
  };
  /** Captured money per seller group */
  allocations: {
    intent_id: string;
    group_id: string;
    owner_type: string;
    seller_id: string | null;
    amount: number;
  };
  /** One row per capture attempt key; a credit-only capture is a succeeded row with amount 0 and no provider call */
  captures: {
    id: string;
    intent_id: string;
    group_id: string | null;
    amount: number;
    /** store-credit share charged with this capture; 0 when none */
    credit_amount: number;
    status: string;
    provider_ref: string | null;
    idempotency_key: string;
    at: Date;
  };
  /** Every adapter call with outcome (no card data) */
  provider_calls: {
    id: string;
    intent_id: string | null;
    refund_id: string | null;
    operation: string;
    outcome: string;
    provider_ref: string | null;
    message: string | null;
    latency_ms: number | null;
    at: Date;
  };
  refunds: {
    id: string;
    ref: string;
    /** null for an orphan payment refund: money without an order */
    order_id: string | null;
    /** checkout session of the payment; what an orphan payment refund is found by */
    checkout_session_id: string;
    intent_id: string;
    origin: 'cancellation' | 'return' | 'case' | 'exception' | 'correction' | 'orphan_payment';
    origin_id: string | null;
    origin_ref: string | null;
    amount: number;
    currency: string;
    destination: string;
    destination_label: string;
    status: 'requested' | 'processing' | 'sent' | 'failed' | 'cancelled';
    attempts: number;
    outcome_unknown: boolean;
    failure_code: string | null;
    failure_reason: string | null;
    provider_ref: string | null;
    reason: string;
    requested_by: Json;
    idempotency_key: string;
    /** provider method id or single-use token of a customer-chosen new destination; kept until the refund is sent or cancelled, then cleared */
    destination_ref: string | null;
    /** provider idempotency key of the attempt in flight; status checks and retries of that attempt reuse it */
    attempt_key: string | null;
    sent_at: Date | null;
    last_attempt_at: Date | null;
    next_attempt_at: Date | null;
    created_at: Date;
    updated_at: Date;
  };
  /** Refund amount per order item; the cap check sums these */
  refund_items: {
    refund_id: string;
    order_item_id: string;
    group_id: string;
    seller_id: string | null;
    amount: number;
  };
  refund_log: {
    id: string;
    refund_id: string;
    from_status: string | null;
    to_status: string;
    detail: string | null;
    actor: Json;
    at: Date;
  };
  disputes: {
    id: string;
    ref: string;
    kind: string;
    provider: string;
    provider_case_id: string;
    intent_id: string;
    order_id: string;
    group_id: string | null;
    seller_id: string | null;
    reason_code: string;
    reason: string;
    amount: number;
    currency: string;
    evidence_due_at: Date | null;
    /** when payments.dispute-deadlines flagged the evidence due within 48 h; once per dispute */
    due_soon_flagged_at: Date | null;
    status: string;
    /** DisputeEvidence: text, file ids and refs, submitted at and by */
    evidence: Json;
    /** a concession waiting for approval: the access approval request; cleared when decided */
    approval_request_id: string | null;
    /** reason given with the concession waiting for approval */
    concession_reason: string | null;
    owner_staff_id: string | null;
    opened_at: Date;
    decided_at: Date | null;
  };
  /** Dispute history: opened, owner set, evidence saved and submitted, concession asked and decided, deadlines, outcome (Dispute.history) */
  dispute_log: {
    id: string;
    dispute_id: string;
    label: string;
    detail: string | null;
    /** Actor */
    actor: Json;
    at: Date;
  };
  /** Provider tokens only: brand, last 4, expiry, label */
  saved_methods: {
    id: string;
    customer_id: string;
    provider: string;
    provider_method_id: string;
    kind: string;
    brand: string;
    last4: string;
    exp_month: number;
    exp_year: number;
    label: string;
    billing_address: Json;
    is_default: boolean;
    removed_at: Date | null;
    created_at: Date;
  };
  /** Raw provider events, deduplicated by provider event id */
  webhook_events: {
    id: string;
    provider: string;
    external_id: string;
    type: string;
    payload: Json;
    /** the payment the event was applied to */
    intent_id: string | null;
    /** the refund the event was applied to */
    refund_id: string | null;
    received_at: Date;
    processed_at: Date | null;
    outcome: string | null;
  };
  /** Daily counters for RF- and CB- references */
  ref_sequences: {
    kind: string;
    day: string;
    last_value: number;
  };
}

